CMD ["python", "-c", "import os, shutil; import mlflow.artifacts; print('Downloading model...'); model_uri = f'models:/' + os.getenv('MODEL_NAME') + '/' + os.getenv('MODEL_STAGE'); dst = '/app/models/production'; shutil.rmtree(dst, ignore_errors=True); mlflow.artifacts.download_artifacts(model_uri, dst_path=dst); print('Model downloaded'); import uvicorn; uvicorn.run('main:app', host='0.0.0.0', port=8000)"]